// slayerblock.mp3, shieldblock.mp3), decoded to 44100 Hz mono 16-bit, each cut to where its sound is (the silence
// before it and the hush after it off, a 15 ms fade-out so none ends on a click), its offset removed, and each set to
// the same loudness as the other three: by a K-weighted measure (the ITU-R BS.1770 filter) the loudest 400 ms of each
// is -22.2 to -22.5 dB and the loudest 200 ms -19.5 to -19.7 dB (full scale 0), so four enemies sound as loud as each
// other. The gain is in the numbers: impact_sound.cpp plays them as they are. They replace v18's single
// "blockedattack.mp3" sound (blockSound).
